<?php get_header(); while (have_posts()) : the_post(); ?><article <?php post_class('single-story container'); ?>><?php fin_breadcrumb('Journal / ' . get_the_title()); ?><header class="article-header"><h1><?php the_title(); ?></h1><div class="article-meta"><span><?php the_author(); ?></span><time datetime="<?php echo esc_attr(get_the_date('c')); ?>"><?php echo esc_html(get_the_date('d.m.Y')); ?></time><span><?php echo esc_html(max(1, (int) ceil(count(preg_split('/\\s+/u', trim(wp_strip_all_tags(get_the_content())), -1, PREG_SPLIT_NO_EMPTY)) / 180))); ?> min read</span></div></header><?php if (has_post_thumbnail()) : ?><div class="article-cover"><?php the_post_thumbnail('full'); ?></div><?php endif; ?><div class="prose article-body"><?php the_content(); wp_link_pages(); ?><div class="post-tags"><?php the_tags('Topics: ', ', '); ?></div></div><div class="post-navigation"><?php the_post_navigation(['prev_text' => '← %title', 'next_text' => '%title →']); ?></div><?php if (comments_open() || get_comments_number()) comments_template(); ?></article><?php endwhile; ?><section class="container section"><div class="section-heading"><h2>Stay <em>a little longer.</em></h2><a class="text-link" href="<?php echo esc_url(fin_page_url('journal')); ?>">All stories ↗</a></div><?php fin_journal(3); ?></section><?php get_footer(); ?>
